update news set tldr='Google, Pixel 11 serisini 12 Ağustos 2026''da tanıttı. Aile 4 modelden oluşuyor (Pixel 11, Pro, Pro XL, Pro Fold), fiyatlar 899 dolardan başlıyor.', table_data='[{"k":"Tanıtım tarihi","v":"12 Ağustos 2026"},{"k":"Model sayısı","v":"4 (Pixel 11, Pro, Pro XL, Pro Fold)"},{"k":"Yonga seti","v":"Tensor G6 (2nm)"},{"k":"Başlangıç fiyatı","v":"899 dolar"},{"k":"Pro Fold fiyatı","v":"1.899 dolar"}]'::jsonb, faq='[{"q":"Google Pixel 11 kaç modelden oluşuyor?","a":"Pixel 11 ailesi 4 modelden oluşuyor: standart Pixel 11, Pixel 11 Pro, Pixel 11 Pro XL ve katlanabilir Pixel 11 Pro Fold."},{"q":"Pixel 11 serisinin fiyatı ne kadar?","a":"Standart Pixel 11 yaklaşık 899 dolardan başlıyor, Pro Fold modeli ise 1.899 dolara kadar çıkıyor."},{"q":"Pixel 11 hangi işlemciyi kullanıyor?","a":"Seri, TSMC''nin 2 nanometre üretim sürecinde üretilen yeni Tensor G6 yonga setini kullanıyor."}]'::jsonb, conclusion='Google Pixel 11 ailesi, 12 Ağustos 2026''da 4 modelle tanıtıldı ve Tensor G6 yonga setiyle donatıldı. Fiyatlar 899-1.899 dolar aralığında; Türkiye satış tarihi henüz açıklanmadı.' where id='google-pixel-11-serisi-tanitildi';
update news set tldr='HUAWEI, Pura 90s telefonu, MatePad Air 2026 tableti ve Watch Kids X1 akıllı saatini 19 Ağustos 2026''da Türkiye''de satışa sunuyor.', table_data='[{"k":"Satış tarihi","v":"19 Ağustos 2026"},{"k":"Ürün sayısı","v":"3 (telefon, tablet, çocuk saati)"},{"k":"Satış kanalı","v":"HUAWEI çevrim içi mağaza + yetkili satıcılar"}]'::jsonb, faq='[{"q":"HUAWEI Pura 90s ne zaman satışa çıkıyor?","a":"19 Ağustos 2026''da HUAWEI''nin kendi mağazası ve yetkili satış noktalarında satışa sunuluyor."},{"q":"Watch Kids X1 kimin için tasarlandı?","a":"HUAWEI Watch Kids X1, ebeveyn kontrolü ve çocuk güvenliğine odaklanan, çocuklara özel bir akıllı saat modeli."}]'::jsonb, conclusion='HUAWEI, 19 Ağustos 2026''da üç farklı kategoride (telefon, tablet, çocuk saati) aynı anda ürün lansmanı yapıyor. Türkiye''ye özel fiyat ve tarih bilgisi henüz netleşmedi.' where id='huawei-pura-90s-matepad-air-2026-watch-kids-x1';
update news set tldr='Sızıntılara göre iPhone 18 Pro Max, Apple''ın ilk donanımsal değişken diyaframlı kamerasına sahip olacak. Sony IMX905 sensörü kullanılacak, model Eylül 2026''da tanıtılması bekleniyor.', table_data='[{"k":"Beklenen tanıtım","v":"Eylül 2026"},{"k":"Ana kamera sensörü","v":"Sony IMX905"},{"k":"Piksel boyutu","v":"1,22 mikron (değişmedi)"},{"k":"Fiyat artışı iddiası","v":"~200 dolar"}]'::jsonb, faq='[{"q":"iPhone 18 Pro Max''te değişken diyafram var mı?","a":"Sızıntılara göre evet — Apple''ın telefon tarihinde ilk kez donanımsal değişken diyafram mekanizması kullanılacak."},{"q":"iPhone 18 Pro Max ne zaman tanıtılacak?","a":"Apple''ın geleneksel takvimine göre Eylül 2026''da tanıtılması bekleniyor."},{"q":"iPhone 18 Pro Max''in fiyatı artacak mı?","a":"Artan bileşen maliyetleri nedeniyle önceki nesle göre yaklaşık 200 dolar daha pahalı olabileceği iddia ediliyor."}]'::jsonb, conclusion='iPhone 18 Pro Max için sızan bilgiler, Apple''ın ilk kez donanımsal değişken diyafram kullanacağını gösteriyor. Sony IMX905 sensörlü model Eylül 2026''da resmen tanıtılana kadar bu bilgiler doğrulanmadı.' where id='iphone-18-pro-max-kamera-sizintisi-degisken-diyafram';
update news set tldr='Galaxy S27 Ultra sızıntıları, 3x telefoto lensin kaldırılabileceğini, LPDDR6 belleğe geçişi ve 5000 mAh sınırının aşılabileceğini gösteriyor. Model 2027 başında (muhtemelen Şubat) bekleniyor.', table_data='[{"k":"Beklenen tanıtım","v":"Şubat 2027 (tahmini)"},{"k":"Ana sensör","v":"200MP ISOCELL HP6 (iddia)"},{"k":"Bellek","v":"LPDDR6 (iddia)"},{"k":"İşlemci","v":"Snapdragon 8 Elite Gen 6 Pro (iddia)"},{"k":"Batarya","v":"5000mAh sınırının üzerinde (iddia)"}]'::jsonb, faq='[{"q":"Galaxy S27 Ultra ne zaman çıkacak?","a":"2027''nin başında, muhtemelen Şubat ayında tanıtılması bekleniyor."},{"q":"Galaxy S27 Ultra''da 3x telefoto lens olacak mı?","a":"Sızıntılara göre S21 Ultra''dan bu yana kullanılan 10MP 3x telefoto lens tamamen kaldırılabilir."},{"q":"Galaxy S27 Ultra bataryası kaç mAh olacak?","a":"Samsung''un Ultra serisinde yıllardır sabit kalan 5000mAh sınırını nihayet aşabileceği iddia ediliyor."}]'::jsonb, conclusion='Galaxy S27 Ultra için ortaya çıkan sızıntılar, Samsung''un yıllardır koruduğu tasarımı kökten değiştirebileceğine işaret ediyor. Bilgiler erken dönem prototiplere dayanıyor ve resmi tanıtıma kadar değişebilir.' where id='samsung-galaxy-s27-ultra-sizintilari-tasarim-degisiyor';
update news set tldr='Honor, robotik kollu kamera sistemine sahip Robot Phone modelini Ağustos 2026''da tanıtacağını doğruladı. ARRI iş birliğiyle sinema kalitesinde görüntü hedefleniyor.', table_data='[{"k":"Beklenen tanıtım","v":"Ağustos 2026 (12 Ağustos iddiası)"},{"k":"Kamera ortağı","v":"ARRI"},{"k":"Ön sipariş","v":"Çin''de başladı"}]'::jsonb, faq='[{"q":"Honor Robot Phone''un özelliği ne?","a":"Klasik sabit kamera adası yerine robotik bir kol üzerine yerleştirilmiş hareketli kamera sistemi kullanıyor."},{"q":"Honor Robot Phone Türkiye''ye gelecek mi?","a":"Henüz belirsiz — bu tür deneysel modeller genellikle önce sınırlı pazarlarda satışa çıkıyor."}]'::jsonb, conclusion='Honor, Ağustos 2026''da robotik kamera koluna sahip deneysel bir telefon tanıtacak. Kesin özellikler ve satış bölgeleri resmi lansmanla netleşecek.' where id='honor-robot-phone-lansman-tarihi';
update news set tldr='Huawei, katlanabilir dizüstü bilgisayarının ikinci neslini Çin''de tanıttı. MateBook Fold Ultimate Design, 24.999 yuandan (~3.700 dolar) başlıyor.', table_data='[{"k":"Başlangıç fiyatı","v":"24.999 yuan (~3.700 dolar)"},{"k":"En üst versiyon","v":"29.999 yuan (~4.440 dolar)"},{"k":"Bellek seçenekleri","v":"24GB+512GB, 24GB+1TB, 32GB+2TB"}]'::jsonb, faq='[{"q":"Huawei MateBook Fold''un fiyatı ne kadar?","a":"24.999 yuandan (yaklaşık 3.700 dolar) başlıyor, en üst versiyon 29.999 yuana (yaklaşık 4.440 dolar) kadar çıkıyor."},{"q":"Bu Huawei''nin kaçıncı katlanabilir dizüstüsü?","a":"İkinci nesil — şirket geçen yılki modelin ardından bu formatı sürdürüyor."}]'::jsonb, conclusion='Huawei, katlanabilir dizüstü kategorisinde ikinci nesil ürününü Çin''de tanıttı. Küresel pazarlara gelip gelmeyeceği henüz açıklanmadı.' where id='huawei-matebook-fold-ultimate-design-2026-tanitildi';
update news set tldr='Nothing''in alt markası CMF, ilk açık tasarımlı (OWS) kulaklığı Clip Pro''yu 4 Ağustos 2026''da tanıttı.', table_data='[{"k":"Tanıtım tarihi","v":"4 Ağustos 2026"},{"k":"Kategori","v":"Açık tasarımlı kulaklık (OWS)"},{"k":"Marka","v":"CMF (Nothing alt markası)"}]'::jsonb, faq='[{"q":"CMF Clip Pro nedir?","a":"Nothing''in alt markası CMF''nin ilk açık tasarımlı kablosuz kulaklığı — kulağı saran, kulak kanalını tıkamayan bir yapıya sahip."},{"q":"Açık tasarımlı kulaklık ne işe yarar?","a":"Kulak kanalını kapatmadığı için özellikle spor yaparken veya çevre sesini duymaya devam etmek isteyenler tarafından tercih ediliyor."}]'::jsonb, conclusion='CMF, Clip Pro ile ürün yelpazesine yeni bir kategori ekledi. Tam teknik özellikler ve Türkiye satış planı henüz netleşmedi.' where id='cmf-clip-pro-acik-tasarimli-kulaklik-tanitildi';
update news set tldr='Huawei Watch GT 7 serisi Çin''de tanıtıldı. Standart ve Pro modelden oluşan seri, 3.000 nit ekran parlaklığı ve 21 güne varan pil ömrü sunuyor, fiyatlar 1.588 yuandan başlıyor.', table_data='[{"k":"Ekran parlaklığı","v":"3.000 nit"},{"k":"Pil ömrü (hafif kullanım)","v":"21 gün"},{"k":"Pil ömrü (normal kullanım)","v":"12 gün"},{"k":"Başlangıç fiyatı","v":"1.588 yuan (41mm)"},{"k":"Pro model fiyatı","v":"2.688 yuan (~399 dolar)"}]'::jsonb, faq='[{"q":"Huawei Watch GT 7''nin pil ömrü ne kadar?","a":"Hafif kullanımda 21 güne, normal kullanımda 12 güne, her zaman açık ekranla 7 güne kadar dayanıyor."},{"q":"Watch GT 7 ve GT 7 Pro arasındaki fark nedir?","a":"Standart model paslanmaz çelik/plastik kasa kullanırken, Pro model titanyum/seramik kombinasyonu ve ek olarak EKG sensörü sunuyor."},{"q":"Watch GT 7 Türkiye''de ne zaman satışa çıkacak?","a":"Küresel satış tarihi ve Türkiye fiyatları henüz açıklanmadı."}]'::jsonb, conclusion='Huawei Watch GT 7 serisi, 21 güne varan pil ömrü ve 3.000 nit ekranıyla Çin''de satışa sunuldu. Fiyatlar 1.588 yuandan başlıyor, küresel lansman tarihi bekleniyor.' where id='huawei-watch-gt-7-serisi-tanitildi-21-gun-pil';
update news set tldr='Galaxy Tab S12 Ultra, Geekbench''te SM-X946B model numarasıyla ortaya çıktı. Sızıntı, Samsung''un ilk kez MediaTek Dimensity 9500 kullanacağını gösteriyor. Eylül 2026''da tanıtılması bekleniyor.', table_data='[{"k":"Model numarası","v":"SM-X946B"},{"k":"Tek çekirdek puanı","v":"2.424"},{"k":"Çok çekirdek puanı","v":"8.446"},{"k":"RAM (test edilen)","v":"12GB"},{"k":"Beklenen işlemci","v":"MediaTek Dimensity 9500"},{"k":"Beklenen tanıtım","v":"Eylül 2026 (Galaxy S26 FE ile)"}]'::jsonb, faq='[{"q":"Galaxy Tab S12 Ultra hangi işlemciyi kullanacak?","a":"Geekbench sızıntısı, Samsung''un tarihsel olarak kullandığı Qualcomm yerine MediaTek''in henüz duyurulmamış Dimensity 9500''ünü işaret ediyor."},{"q":"Galaxy Tab S12 Ultra ne zaman tanıtılacak?","a":"Samsung''un alışılmış takvimine göre Eylül 2026''da Galaxy S26 FE ile birlikte tanıtılması bekleniyor."}]'::jsonb, conclusion='Galaxy Tab S12 Ultra''nın Geekbench''te görülmesi, Samsung''un tablet tarafında MediaTek''e geçebileceğine işaret ediyor. Resmi tanıtım Eylül 2026''da bekleniyor.' where id='samsung-galaxy-tab-s12-ultra-geekbench-sizintisi';
update news set tldr='LG, 9mm kalınlığındaki kablosuz OLED evo W6 Wallpaper TV''yi Türkiye''de satışa sundu. 77 ve 83 inç seçenekleri var, 31 Ağustos''a kadar alanlara kablosuz hoparlör hediye ediliyor.', table_data='[{"k":"Kalınlık","v":"9 mm"},{"k":"Ekran boyutları","v":"77\" ve 83\""},{"k":"Kablosuz teknoloji","v":"True Wireless + Zero Connect Box"},{"k":"Hediye kampanyası","v":"31 Ağustos 2026''ya kadar Sound Suite M7"}]'::jsonb, faq='[{"q":"LG OLED W6 kaç mm kalınlığında?","a":"Sadece 9 mm — görüntü ve ses işleme donanımı ayrı bir kutuda (Zero Connect Box) bulunuyor."},{"q":"LG OLED W6 hangi ekran boyutlarında satılıyor?","a":"77 inç ve 83 inç olmak üzere iki seçenekte satışa sunuldu."},{"q":"LG OLED W6 alana hediye var mı?","a":"31 Ağustos 2026''ya kadar satın alanlara Sound Suite M7 kablosuz hoparlör seti hediye ediliyor."}]'::jsonb, conclusion='LG''nin OLED evo W6 Wallpaper TV''si, 9mm kalınlığı ve kablosuz bağlantı teknolojisiyle Türkiye''de satışa sunuldu. Kampanya 31 Ağustos 2026''da sona eriyor.' where id='lg-oled-w6-wallpaper-tv-turkiyede';
